'use strict';

function isPlainObject(value) {
  if (value === null || typeof value !== 'object') return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function updateMember(members, memberId, patch) {
  if (!Array.isArray(members)) throw new TypeError('members must be an array');
  if (typeof memberId !== 'string' || memberId.length === 0) throw new TypeError('invalid memberId');
  if (!isPlainObject(patch)) throw new TypeError('patch must be a plain object');

  for (const member of members) {
    if (!isPlainObject(member) || typeof member.id !== 'string' || member.id.length === 0) {
      throw new TypeError('invalid member');
    }
  }

  const allowed = new Set(['displayName', 'email', 'location']);
  for (const key of Object.keys(patch)) {
    if (!allowed.has(key)) throw new TypeError('unknown patch field');
  }
  for (const key of ['displayName', 'email']) {
    if (key in patch && (typeof patch[key] !== 'string' || patch[key].length === 0)) {
      throw new TypeError('invalid patch field');
    }
  }
  if ('location' in patch) {
    if (!isPlainObject(patch.location)) throw new TypeError('invalid location');
    const locationAllowed = new Set(['street', 'city', 'postalCode']);
    for (const key of Object.keys(patch.location)) {
      if (!locationAllowed.has(key)) throw new TypeError('unknown location field');
      if (typeof patch.location[key] !== 'string' || patch.location[key].length === 0) {
        throw new TypeError('invalid location field');
      }
    }
  }

  const index = members.findIndex((member) => member.id === memberId);
  if (index === -1) throw new Error('Member not found');

  const current = members[index];
  const updated = { ...current, ...patch };
  if ('location' in patch) {
    updated.location = { ...patch.location };
  }
  const result = members.slice();
  result[index] = updated;
  return { members: result, updated };
}

module.exports = { updateMember };

