'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['updateMember']);
const { updateMember } = api;
const typeError = fn => assert.throws(fn, TypeError);

const first = { id: 'a', displayName: 'Ann', location: { street: '1st', city: 'Old' } };
const second = { id: 'b', email: 'b@old.test' };
const patch = { displayName: 'Bee', location: { city: 'New', postalCode: '123' } };
const result = updateMember([first, second], 'a', patch);
assert.deepStrictEqual(result, {
  members: [
    { id: 'a', displayName: 'Bee', location: { street: '1st', city: 'New', postalCode: '123' } },
    second
  ],
  updated: { id: 'a', displayName: 'Bee', location: { street: '1st', city: 'New', postalCode: '123' } }
});
assert.notStrictEqual(result.members, [first, second]);
assert.notStrictEqual(result.members[0], first);
assert.strictEqual(result.members[1], second);
assert.strictEqual(result.updated, result.members[0]);
assert.notStrictEqual(result.updated.location, patch.location);
patch.displayName = 'changed';
patch.location.city = 'changed';
assert.strictEqual(result.updated.displayName, 'Bee');
assert.strictEqual(result.updated.location.city, 'New');
assert.deepStrictEqual(first, { id: 'a', displayName: 'Ann', location: { street: '1st', city: 'Old' } });

const empty = updateMember([first, second], 'b', {});
assert.notStrictEqual(empty.members, result.members);
assert.notStrictEqual(empty.members[1], second);
assert.strictEqual(empty.members[0], first);
assert.deepStrictEqual(empty.updated, second);

assert.throws(() => updateMember([first], 'missing', {}), err => err instanceof Error && err.message === 'Member not found');
typeError(() => updateMember({}, 'a', {}));
typeError(() => updateMember([null], 'a', {}));
typeError(() => updateMember([{ id: '' }], 'a', {}));
typeError(() => updateMember([{ id: 'a' }], '', {}));
typeError(() => updateMember([{ id: 'a' }], 'a', []));
typeError(() => updateMember([{ id: 'a' }], 'a', { role: 'x' }));
typeError(() => updateMember([{ id: 'a' }], 'a', { email: '' }));
typeError(() => updateMember([{ id: 'a' }], 'a', { displayName: 1 }));
typeError(() => updateMember([{ id: 'a' }], 'a', { location: { city: 'x', country: 'y' } }));
typeError(() => updateMember([{ id: 'a' }], 'a', { location: { street: '' } }));

